"""Export complete shift tables and offline schematic; never deploys a Site."""
import csv,hashlib,html,json,math
from pathlib import Path
import monument_slide as s
ROOT=s.ROOT

def export():
 actual=json.loads((ROOT/'results/FOLD-SLIDE-020-actual.json').read_text());records=actual['records'];nulls={name:json.loads((ROOT/f'results/FOLD-SLIDE-020-null-{name}.json').read_text()) for name in ('shuffle','rotation')};by_null={name:{x['id']:x for x in r['per_frame']} for name,r in nulls.items()}
 fields=['model','shift','geometric_overlap_cells','comparable_letter_pairs','label_matches','label_match_fraction','full_mask_coincidences','nonempty_common_aperture_pairs','common_pixel_area','union_pixel_area','common_over_union','matched_letters','k4_matches']
 with (ROOT/'results/FOLD-SLIDE-020-frames.csv').open('w') as out:
  extra=['expected_label_matches','expected_common_pixels']+[scheme+'_'+endpoint+'_adjusted_p' for scheme in nulls for endpoint in ('label','area')];writer=csv.DictWriter(out,fieldnames=fields+extra,lineterminator="\n");writer.writeheader()
  for row in records:
   result={k:(len(row[k]) if k=='k4_matches' else row[k]) for k in fields};result.update(expected_label_matches=row['expected'][0],expected_common_pixels=row['expected'][1])
   for scheme in nulls:
    for endpoint,key in [('label','label_matches'),('area','common_pixel_area')]:
     value=by_null[scheme][row['id']]['endpoints'][key];result[scheme+'_'+endpoint+'_adjusted_p']=value['four_report_adjusted_p'] if value else None
   writer.writerow(result)
 with (ROOT/'results/FOLD-SLIDE-020-matches.csv').open('w') as out:
  writer=csv.writer(out,lineterminator="\n");writer.writerow(['model','shift','letter','cipher_row','cipher_column','cipher_raw_character','cipher_glyph_position','k4_position','tableau_row','tableau_column','tableau_raw_character'])
  for row in records:
   for match in row['matches']:
    c,t=match['cipher'],match['tableau'];writer.writerow([row['model'],row['shift'],c['character'],c['row'],c['column'],c['raw_row_character'],c['glyph_position'],c['k4_position'],t['row'],t['column'],t['raw_row_character']])
 m=s.Model();glyph=json.loads((ROOT/'data/fold-aperture-surrogate-v1.json').read_text())['glyph_rows'];payload=dict(input=m.data,glyphs=glyph,records=[{k:r[k] for k in fields if k not in ('matched_letters','k4_matches')} for r in records]);encoded=json.dumps(payload,separators=(',',':')).replace('</','<\\/')
 page=r'''<!doctype html><meta charset="utf-8"><title>Kryptos fold and slide — flat surrogate</title><style>body{font:15px system-ui;background:#eeeade;color:#252b28;margin:24px auto;max-width:1040px;padding:0 18px}h1{font-size:25px}label{display:inline-block;margin:6px}input{width:min(550px,70vw)}button,select{padding:7px}canvas{max-width:100%;height:auto;background:#625246}aside{background:#fff6dc;padding:12px;border-left:5px solid #b0852d}.layout{display:flex;gap:20px;align-items:flex-start;flex-wrap:wrap}#metrics{max-width:300px;white-space:pre-line}small{display:block;line-height:1.5}a{color:#25635d}</style><h1>Fold, align, then pull one column at a time</h1><aside>Unmeasured flat-grid illustration using the existing modeled square-aperture font. It does not simulate the sculpture’s surveyed glyphs, curvature, thickness, illumination or actual foldability.</aside><p>The initial tableau view is mirrored; the fold reflects it again. <b>The glyphs below face the same way.</b> At zero, the observed anchor is MYVGT opposite AABCD in column 2; no row shift is applied.</p><label>Registration <select id="model"><option>OBSERVED_RENDER33</option><option>DUNIN_HEADER33</option></select></label><label>View <select id="view"><option value="and">Common aperture</option><option value="cipher">Cipher layer</option><option value="tableau">Folded tableau</option></select></label><p><button id="minus">← one column</button> <button id="zero">Full overlap</button> <button id="plus">one column →</button></p><input id="shift" type="range" min="-33" max="33" value="0" step="1"><output id="step"></output><div class="layout"><canvas id="canvas" width="693" height="756"></canvas><div id="metrics"></div></div><small>White squares show the selected view: common open area or an individual layer. Counters always describe the common aperture. Green borders mark identical A–Z labels. Gray cells are outside the two-sheet overlap and excluded from its denominator. Blank/padding cells are solid copper. Different glyphs can share openings. No partial aperture fragment is interpreted as a new letter.</small><p><a href="../../results/FOLD-SLIDE-020-frames.csv">Every shift: counts and overlap denominators</a> · <a href="../MONUMENT-FOLD-SLIDE-FINDINGS.md">Source, controls and limitations</a></p><script>
const DATA=__PAYLOAD__,W=DATA.input.width,H=DATA.input.cipher_rows.length,Z=Array(7).fill('00000'),center=rows=>rows.map(row=>' '.repeat(Math.floor((W-row.length)/2))+row+' '.repeat(W-row.length-Math.floor((W-row.length)/2))),C=center(DATA.input.cipher_rows),T=Object.fromEntries(Object.entries(DATA.input.models).map(([k,v])=>[k,center(v)]));
function foldCompute(model,shift){let labels=0,area=0,nonempty=0,full=0,eligible=0,union=0,overlap=0;for(let r=0;r<H;r++)for(let c=0;c<W;c++){let j=c-shift;if(j<0||j>=W)continue;overlap++;let a=C[r][c],b=T[model][r][j],A=DATA.glyphs[a]||Z,B=DATA.glyphs[b]||Z;if(/[A-Z]/.test(a)&&/[A-Z]/.test(b)){eligible++;labels+=a===b;}let common=0,same=true;for(let y=0;y<7;y++)for(let x=0;x<5;x++){common+=A[y][x]==='1'&&B[y][x]==='1';union+=A[y][x]==='1'||B[y][x]==='1';same&&=A[y][x]===B[y][x];}area+=common;nonempty+=common>0;full+=common>0&&same;}return{geometric_overlap_cells:overlap,comparable_letter_pairs:eligible,label_matches:labels,common_pixel_area:area,nonempty_common_aperture_pairs:nonempty,full_mask_coincidences:full,union_pixel_area:union};}
globalThis.foldCompute=foldCompute;const $=id=>document.getElementById(id);
function render(){const shift=Number($('shift').value),model=$('model').value,view=$('view').value,ctx=$('canvas').getContext('2d'),n=foldCompute(model,shift);ctx.clearRect(0,0,693,756);for(let r=0;r<H;r++)for(let c=0;c<W;c++){const j=c-shift,inside=j>=0&&j<W,a=C[r][c],b=inside?T[model][r][j]:' ',A=DATA.glyphs[a]||Z,B=DATA.glyphs[b]||Z;ctx.fillStyle=inside?'#625246':'#c8c8bd';ctx.fillRect(c*21,r*27,21,27);for(let y=0;y<7;y++)for(let x=0;x<5;x++){let open=view==='cipher'?A[y][x]==='1':view==='tableau'?inside&&B[y][x]==='1':inside&&A[y][x]==='1'&&B[y][x]==='1';if(open){ctx.fillStyle='#fffce7';ctx.fillRect(c*21+(x+1)*3,r*27+(y+1)*3,3,3);}}if(inside&&a===b&&/[A-Z]/.test(a)){ctx.strokeStyle='#77dca3';ctx.lineWidth=1;ctx.strokeRect(c*21+.5,r*27+.5,20,26);}}$('step').textContent=' displacement '+shift;$('metrics').textContent='Shift '+shift+' columns\n\nOverlap cells: '+n.geometric_overlap_cells+'\nComparable letter pairs: '+n.comparable_letter_pairs+'\nIdentical labels: '+n.label_matches+'\nNonempty common apertures: '+n.nonempty_common_aperture_pairs+'\nCommon square pixels: '+n.common_pixel_area+'\nFull glyph coincidences: '+n.full_mask_coincidences+'\n\n'+(n.geometric_overlap_cells?'Increasing displacement changes the overlap denominator.':'No two-layer overlap remains; ratios are undefined.');}
$('shift').oninput=render;$('model').onchange=render;$('view').onchange=render;$('minus').onclick=()=>{$('shift').value=Math.max(-W,Number($('shift').value)-1);render();};$('plus').onclick=()=>{$('shift').value=Math.min(W,Number($('shift').value)+1);render();};$('zero').onclick=()=>{$('shift').value=0;render();};render();
</script>'''.replace('__PAYLOAD__',encoded)
 directory=ROOT/'research/figures';directory.mkdir(exist_ok=True);(directory/'fold-slide-020.html').write_text(page)
 # Compact static count plots, every shift and both registrations.
 svg=['<svg xmlns="http://www.w3.org/2000/svg" width="940" height="520" viewBox="0 0 940 520"><rect width="940" height="520" fill="#f5f2e9"/><text x="30" y="30" font-family="sans-serif" font-size="20">Double-reflection slide — all integer displacements</text>']
 for panel,(key,title,maximum) in enumerate((('label_matches','Identical letter labels',40),('nonempty_common_aperture_pairs','Nonempty modeled aperture intersections',924))):
  top=70+panel*210;svg.append(f'<text x="60" y="{top}" font-family="sans-serif" font-size="15">{title}</text>');svg.append(f'<path d="M60 {top+15}V{top+175}H895" fill="none" stroke="#555"/>')
  for i,name in enumerate(m.targets):
   rows=[r for r in records if r['model']==name];points=' '.join(f'{60+(r["shift"]+33)*835/66:.2f},{top+175-r[key]*155/maximum:.2f}' for r in rows);svg.append(f'<polyline points="{points}" fill="none" stroke="{("#25635d","#b67830")[i]}" stroke-width="2"/>')
  for shift in (-33,-16,0,16,33):svg.append(f'<text x="{60+(shift+33)*835/66-10:.1f}" y="{top+193}" font-family="sans-serif" font-size="11">{shift}</text>')
 svg.append('<text x="60" y="507" font-family="sans-serif" font-size="12">Green: observed render. Brown: header-blank sensitivity. Approximate glyphs; no physical optical calibration.</text></svg>');(directory/'fold-slide-counts-020.svg').write_text(''.join(svg))
 return dict(exports=['results/FOLD-SLIDE-020-frames.csv','results/FOLD-SLIDE-020-matches.csv','research/figures/fold-slide-020.html','research/figures/fold-slide-counts-020.svg'],source_sha256={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in ('results/FOLD-SLIDE-020-actual.json','results/FOLD-SLIDE-020-null-shuffle.json','results/FOLD-SLIDE-020-null-rotation.json')})
if __name__=='__main__':(ROOT/'results/FOLD-SLIDE-020-export.json').write_text(json.dumps(export(),indent=2)+'\n')
